#!/usr/bin/env python3
import asyncio, pathlib, subprocess, tempfile
from playwright.async_api import async_playwright
ROOT=pathlib.Path(__file__).resolve().parents[2]
BUILD=ROOT/'tests/browser/build_template_library_fixture.php'
def fixture():
    return subprocess.check_output(['php',str(BUILD)],cwd=ROOT,text=True)
async def main():
    failed=[]; checks=0
    async def ck(cond,name):
        nonlocal checks
        checks+=1
        if not cond: failed.append(name)
    async with async_playwright() as p:
        browser=await p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage','--disable-gpu'])
        page=await browser.new_page(viewport={'width':1280,'height':900})
        await page.set_content(fixture(),wait_until='load')
        await ck(await page.get_by_role('heading',name='Certificate designs').count()==1,'pageHeading')
        await ck(await page.locator('.certloom-design-nav a').count()==2,'exactlyTwoTabs')
        await ck(await page.locator('.certloom-design-nav a').all_inner_texts()==['Library','My designs'],'libraryMyDesignsTabs')
        await ck(await page.get_by_text('Assignments',exact=True).count()==0,'noAssignmentsTab')
        await ck(await page.get_by_role('heading',name='Certificate library').count()==1,'libraryHeading')
        await ck(await page.get_by_role('button',name='Import').count()==1,'importPrimaryAction')
        await ck(await page.get_by_role('link',name='New design').count()==1,'newDesignPrimaryAction')
        await ck(await page.locator('.certloom-template-library-card').count()==4,'fourGeometryCards')
        await ck(await page.get_by_role('button',name='Preview').count()==4,'previewActions')
        await ck(await page.get_by_role('button',name='Customize').count()==4,'customizeActions')
        await ck(await page.get_by_text('Use for Program',exact=True).count()==0,'noProgramAssignmentActions')
        await ck(await page.get_by_text('Edit in Designer',exact=True).count()==0,'builtinsNotDirectEditable')
        await ck(await page.locator('.certloom-template-card-more a',has_text='Export').count()==4,'exportActions')
        usage=page.locator('.certloom-template-card-more a',has_text='Used by')
        await ck(await usage.count()==4,'usageActions')
        await ck(all('page=certloom-design-rules' in href and 'design_type=certificate' in href for href in await usage.evaluate_all('(els)=>els.map(e=>e.href)')),'usageRoutesToDesignRules')
        await ck(await page.locator('.certloom-template-library-program-filter,.certloom-template-library-program-context,.certloom-library-filter-program').count()==0,'noProgramFilterPlumbing')
        await ck(await page.get_by_text('Certification & Standards',exact=True).count()>=1,'purposeFilterAvailable')
        await ck(await page.get_by_text('English base',exact=True).count()==1,'languageFacet')
        await ck(await page.get_by_text('RTL layout-ready',exact=True).count()==1,'rtlFacet')
        await ck(await page.evaluate('document.documentElement.scrollWidth <= window.innerWidth + 1'),'desktopNoOverflow')
        primary_boxes=await page.locator('.certloom-template-library-filter-primary input, .certloom-template-library-filter-primary select').evaluate_all('(els)=>els.map(e=>e.getBoundingClientRect()).map(r=>({y:r.y,h:r.height}))')
        await ck(len(primary_boxes)==3 and max(abs(b['y']-primary_boxes[0]['y']) for b in primary_boxes)<2,'primaryFilterControlsShareBaseline')
        for index,label in enumerate(('a4Landscape','a4Portrait','letterLandscape','letterPortrait')):
            stage=page.locator('.certloom-template-library-thumbnail-stage').nth(index)
            wrapper=stage.locator('.certloom-template-preview-scroll')
            contained=await stage.evaluate("""(stage)=>{const page=stage.querySelector('.certloom-template-preview-page');if(!page)return false;const s=stage.getBoundingClientRect(),p=page.getBoundingClientRect();return p.left>=s.left-1&&p.top>=s.top-1&&p.right<=s.right+1&&p.bottom<=s.bottom+1;}""")
            await ck(contained,label+'ThumbnailFullyContained')
            await ck(await wrapper.evaluate('(e)=>getComputedStyle(e).overflow==="hidden"'),'noInternalScrollbars'+label.title())
            centered=await stage.evaluate("""(stage)=>{const page=stage.querySelector('.certloom-template-preview-page');const s=stage.getBoundingClientRect(),p=page.getBoundingClientRect();return Math.abs((p.left+p.width/2)-(s.left+s.width/2))<=1.5&&Math.abs((p.top+p.height/2)-(s.top+s.height/2))<=1.5;}""")
            await ck(centered,label+'ThumbnailCentered')
        await ck(await page.locator('[data-fixture-page="a4-landscape"]').count()==1 and await page.locator('[data-fixture-page="a4-portrait"]').count()==1,'a4BothOrientations')
        await ck(await page.locator('[data-fixture-page="letter-landscape"]').count()==1 and await page.locator('[data-fixture-page="letter-portrait"]').count()==1,'letterBothOrientations')
        await ck(await page.locator('.fixture-long-name').count()==4,'longRecipientNamesCovered')
        await ck(await page.locator('.fixture-background').count()>=2,'backgroundContentCovered')
        await ck(await page.locator('.fixture-logo').count()>=2,'logoContentCovered')
        await ck(await page.locator('.certloom-template-preview-page[dir="rtl"]').count()==1,'rtlCertificateContentCovered')
        first=page.locator('[data-certloom-library-preview]').first
        await first.click(); dialog=page.locator('[data-certloom-library-dialog]')
        await ck(await dialog.evaluate('(d)=>d.open'),'previewDialogOpen')
        await ck(await page.locator('[data-certloom-library-dialog-body] .certloom-template-preview-scroll').count()==1,'previewCloned')
        await ck((await page.locator('[data-certloom-library-dialog-title]').inner_text())=='Classic A4 Landscape','previewTitle')
        box=await page.locator('[data-certloom-library-dialog-stage]').bounding_box()
        await ck(bool(box and box['width']>500 and box['height']>300),'largePreviewScale')
        await ck(await page.locator('[data-certloom-library-dialog-stage] .certloom-template-preview-scroll').evaluate('(e)=>getComputedStyle(e).overflow==="hidden"'),'dialogPreviewNoInternalScrollbar')
        await page.get_by_role('button',name='Close').first.click()
        await ck(not await dialog.evaluate('(d)=>d.open'),'previewDialogClose')
        await ck(await first.evaluate('(e)=>document.activeElement===e'),'previewFocusRestored')
        imp=page.get_by_role('button',name='Import')
        await imp.click(); idialog=page.locator('[data-certloom-certificate-import-dialog]')
        await ck(await idialog.evaluate('(d)=>d.open'),'importDialogOpen')
        await ck(await idialog.locator('input[type=file][name=design_package]').count()==1,'importFilePicker')
        await ck(await idialog.get_by_text('not assigned anywhere automatically',exact=False).count()==1,'importAssignmentBoundaryCopy')
        await ck(await idialog.locator('input[type=file]').evaluate('(e)=>document.activeElement===e'),'importFocusesFile')
        await idialog.get_by_role('button',name='Close').click()
        await ck(await imp.evaluate('(e)=>document.activeElement===e'),'importFocusRestored')
        toggle=page.get_by_role('button',name='Start from background')
        panel=page.locator('[data-certloom-library-background-panel]')
        await ck(await panel.get_attribute('hidden') is not None,'backgroundInitiallyCollapsed')
        await toggle.click(); await ck(await panel.get_attribute('hidden') is None,'backgroundExpanded')
        await ck((await toggle.get_attribute('aria-expanded'))=='true','backgroundAriaExpanded')
        choose=page.get_by_role('button',name='Choose image'); await choose.click()
        await ck(await page.evaluate('window.__mediaOpened===true'),'mediaPickerOpened')
        await page.evaluate('window.__lastFrame.__select()')
        await ck((await page.locator('[data-certloom-library-background-id]').input_value())=='42','mediaAttachmentSelected')
        await ck((await page.locator('[data-certloom-library-background-name]').inner_text())=='certificate-background.png','mediaFilenameVisible')
        await ck(not await page.locator('[data-certloom-library-background-submit]').is_disabled(),'backgroundSubmitEnabled')
        await page.close()
        mobile=await browser.new_page(viewport={'width':390,'height':844}); await mobile.set_content(fixture(),wait_until='load')
        await ck(await mobile.evaluate('document.documentElement.scrollWidth <= window.innerWidth + 1'),'mobileNoOverflow')
        action_heights=await mobile.locator('.certloom-template-library-actions .button,.certloom-template-page-actions .button').evaluate_all('(els)=>els.map(e=>e.getBoundingClientRect().height)')
        await ck(all(h>=44 for h in action_heights),'mobileActionsAtLeast44')
        await ck(await mobile.locator('.certloom-template-library-grid').evaluate('(e)=>getComputedStyle(e).gridTemplateColumns.split(" ").length===1'),'mobileSingleColumnCards')
        for index,label in enumerate(('a4Landscape','a4Portrait','letterLandscape','letterPortrait')):
            stage=mobile.locator('.certloom-template-library-thumbnail-stage').nth(index)
            await ck(await stage.evaluate("""(stage)=>{const page=stage.querySelector('.certloom-template-preview-page');if(!page)return false;const s=stage.getBoundingClientRect(),p=page.getBoundingClientRect();return p.left>=s.left-1&&p.top>=s.top-1&&p.right<=s.right+1&&p.bottom<=s.bottom+1;}"""),'mobile'+label.title()+'ThumbnailFullyContained')
        await mobile.close()
        rtl=await browser.new_page(viewport={'width':900,'height':780}); await rtl.set_content(fixture(),wait_until='load'); await rtl.locator('html').evaluate("e=>e.setAttribute('dir','rtl')")
        await ck(await rtl.evaluate('document.documentElement.scrollWidth <= window.innerWidth + 1'),'rtlNoOverflow')
        await ck(await rtl.get_by_role('button',name='Customize').first.is_visible(),'rtlPrimaryActionVisible')
        await rtl.close()
        reduced=await browser.new_page(viewport={'width':900,'height':780},reduced_motion='reduce'); await reduced.set_content(fixture(),wait_until='load')
        await ck(await reduced.evaluate("matchMedia('(prefers-reduced-motion: reduce)').matches"),'reducedMotionActive')
        await ck(await reduced.locator('.certloom-template-library-card').first.is_visible(),'reducedMotionCardsVisible'); await reduced.close()
        forced=await browser.new_page(viewport={'width':900,'height':780},forced_colors='active'); await forced.set_content(fixture(),wait_until='load')
        await ck(await forced.evaluate("matchMedia('(forced-colors: active)').matches"),'forcedColorsActive')
        await ck(await forced.locator('.certloom-template-library-card').first.is_visible(),'forcedColorsCardsVisible'); await forced.close()
        await browser.close()
    if failed:
        print('FAIL  TPLUX-03 Certificate Library browser gate:', ', '.join(failed)); print(f'\n{checks-len(failed)} passed, {len(failed)} failures'); return 1
    print('PASS  TPLUX-03 Certificate Library browser gate: assignment-free discovery, Customize/Export/usage, portable import, canonical preview, background media and responsive accessibility')
    print(f'\n{checks} TPLUX-03 Certificate Library browser checks, 0 failures'); return 0
raise SystemExit(asyncio.run(main()))
